#include "tick_handler.hpp"std::string_view tick_handler::extract_value(std::string_view msg, std::string_view key){        std::string pattern;        pattern.reserve(key.size() + 3);        pattern += '"';        pattern += key;        pattern += "\":";        size_t start = msg.find(pattern);        if (start == std::string_view::npos) return {};        start += pattern.size();        if (start >= msg.size()) return {};        if (msg[start] == '"')        {            start += 1;            size_t end = msg.find('"', start);            if (end == std::string_view::npos) return {};            return msg.substr(start, end - start);        }        else        {            size_t end = msg.find_first_of(",}", start);            if (end == std::string_view::npos) end = msg.size();            return msg.substr(start, end - start);        }}int64_t tick_handler::to_fixed(std::string_view sv, int64_t scale){    if (sv.empty())        throw std::invalid_argument("to_fixed: empty string");    size_t i = 0;    bool negative = false;    if (sv[i] == '-' || sv[i] == '+')    {        negative = (sv[i] == '-');        i++;    }    if (i >= sv.size())        throw std::invalid_argument("to_fixed: no digits found");    int64_t int_part = 0;    int64_t frac_part = 0;    int64_t frac_scale = 1;    bool after_decimal = false;    bool seen_digit = false;    for (; i < sv.size(); i++)    {        char c = sv[i];        if (c == '.')        {            if (after_decimal)                throw std::invalid_argument("to_fixed: multiple decimal points");            after_decimal = true;            continue;        }        if (c < '0' || c > '9')            throw std::invalid_argument("to_fixed: invalid character in number");        int digit = c - '0';        seen_digit = true;        if (!after_decimal)        {            if (int_part > (INT64_MAX - digit) / 10)                throw std::overflow_error("to_fixed: integer part overflow");            int_part = int_part * 10 + digit;        }        else        {            if (frac_scale <= scale)            {                frac_part = frac_part * 10 + digit;                frac_scale *= 10;            }        }    }    if (!seen_digit)        throw std::invalid_argument("to_fixed: no digits found");    int64_t scaled_frac = (frac_part * scale) / frac_scale;    int64_t remainder = (frac_part * scale) % frac_scale;    if (remainder * 2 >= frac_scale)        scaled_frac += 1;    int64_t value = int_part * scale + scaled_frac;    return negative ? -value : value;}bool tick_handler::update_tick(const std::string& tick_msg){    try    {        tick t;        t.symbol = std::string(extract_value(tick_msg, "s"));        t.uid = std::stoull(std::string(extract_value(tick_msg, "u")));        t.ask = to_fixed(extract_value(tick_msg, "a"), SCALE);        t.bid = to_fixed(extract_value(tick_msg, "b"), SCALE);        t.ask_qty = to_fixed(extract_value(tick_msg, "A"), SCALE);        t.bid_qty = to_fixed(extract_value(tick_msg, "B"), SCALE);        if (t.uid <= latest_tick_.uid)            return false;        std::lock_guard<std::mutex> lock(mutex_);        latest_tick_ = t;        return true;    }    catch (std::exception& e)    {        std::cerr << "Failed to parse tick: " << e.what() << std::endl;        throw;    }}int64_t tick_handler::get_bid_price(){    std::lock_guard<std::mutex> lock(mutex_);    return latest_tick_.bid;}int64_t tick_handler::get_ask_price(){    std::lock_guard<std::mutex> lock(mutex_);    return latest_tick_.ask;}int64_t tick_handler::get_ask_qty(){    return latest_tick_.ask_qty;}int64_t tick_handler::get_bid_qty(){    return latest_tick_.bid_qty;}tick tick_handler::get_tick(){    tick tt;    tt.ask_qty = latest_tick_.ask_qty;    tt.bid_qty = latest_tick_.bid_qty;    tt.ask = latest_tick_.ask;    tt.bid = latest_tick_.bid;    return tt;}